// EDIT ME for each run.
// mode 'read' = read the thread only; 'reply' = post reply_text or each of reply_texts (in order) in the thread.
// ticket: if set, nothing is posted when a reply already names it. Messages already in the thread are skipped.
return [{ json: {
  mode: 'reply',
  channel: 'C09GZHLNFRB',
  thread_ts: '1793974370.331779',
  ticket: 'VIN-615',
  reply_texts: [
    '<https://futuremedia.atlassian.net/browse/VIN-615|VIN-615> \u2013 [Sign-up] Non-US users see the US legal text styling below the Continue button\n1 key (EN changed) \u2013 <https://app.lokalise.com/project/2944050668d5010cbd95e8.36175908/?view=multi&filter=tag_b3c51b7bbc16790814a3e8d301a4aa66|click to see>\nCommit <https://github.com/QR-CODE-App/vinchecker-frontend/commit/5464c9a86b849b7e0dbc3789bd833336da6df4d0|5464c9a>\nBug \u2013 no localization ticket (Localization label)',
    '```\n\ud83d\udd39 Key description already written by dev\n\u26a0\ufe0f No screenshots added \u2013 add manually if needed\n\ud83d\udd39 ES updated to the new source\n```'
  ]
} }];

const cfg = $('Config').first().json;
const r = $('Read Thread').first().json;
if (!r.ok) throw new Error('Slack error: ' + r.error + ' (is the bot invited to the channel?)');
const msgs = (r.messages || []).map(m => ({ ts: m.ts, user: m.user || m.bot_id, text: m.text }));
if (cfg.mode !== 'reply') return [{ json: { thread: msgs, posted: false } }];
const texts = cfg.reply_texts || (cfg.reply_text ? [cfg.reply_text] : []);
if (!texts.length) throw new Error('reply mode needs reply_text or reply_texts');
if (cfg.ticket && msgs.slice(1).some(m => (m.text || '').includes(cfg.ticket))) return [{ json: { thread: msgs, posted: false, skipped: 'a reply already names ' + cfg.ticket } }];
const existing = msgs.slice(1).map(m => (m.text || '').slice(0, 60));
const todo = texts.filter(t => !existing.includes(t.slice(0, 60)));
if (!todo.length) return [{ json: { thread: msgs, posted: false, skipped: 'all messages already in thread' } }];
return todo.map(t => ({ json: { post: { channel: cfg.channel, thread_ts: cfg.thread_ts, text: t, unfurl_links: false } } }));
